import React, { useEffect, useState } from 'react';
import axios from "axios";
import { useParams } from "react-router-dom";
import ImageGallery from "react-image-gallery";
import "react-image-gallery/styles/css/image-gallery.css"; // Don't forget to import the CSS

function ProductsPage() {
    const { categoryId } = useParams();
    const [products, setProducts] = useState([]);
    const [error, setError] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            setError(null);
            try {
                const url = categoryId
                    ? `http://localhost:3000/product?categoryId=${categoryId}`
                    : 'http://localhost:8080/product';
                const response = await axios.get(url);
                setProducts(response.data);
            } catch (err) {
                setError(err);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, [categoryId]);

    if (loading) {
        return <div>Loading...</div>;
    }
    if (error) {
        return <div>Error: {error.message}</div>;
    }

    return (
        <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
            <h1>{categoryId ? `Products in Category ${categoryId}` : 'All Products'}</h1>
            {products.length > 0 ? (
                // Use a different HTML structure for better layout
                <div>
                    {products.map(product => {
                        // 1. Check if the product has images
                        if (!product.images || product.images.length === 0) {
                            return (
                                <div key={product.id} style={{ marginBottom: '40px' }}>
                                    <h2>{product.name}</h2>
                                    <p>No images available for this product.</p>
                                </div>
                            );
                        }

                        // 2. Format the images for the ImageGallery component
                        const imagesForGallery = product.images.map(image => ({
                            original: image.path,
                            thumbnail: image.path, // Use the same image for the thumbnail
                            description: product.name,
                        }));

                        // 3. Render the ImageGallery component with the formatted data
                        return (
                            <div key={product.id} style={{ marginBottom: '40px' }}>
                                <h2>{product.name}</h2>
                                <ImageGallery items={imagesForGallery} showThumbnails={true} />
                            </div>
                        );
                    })}
                </div>
            ) : (
                <p>No products found for this category.</p>
            )}
        </div>
    );
}

export default ProductsPage;
